package player

import (
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"testing"

	"github.com/txdywmwddhxs/mahjong-engine-cli/src/card"
	"github.com/txdywmwddhxs/mahjong-engine-cli/src/replay"
)

// Hash all recorded frames, including hand order, score item order, settlement
// details and intermediate states. Expected hashes were captured before the
// pure-analysis refactor, rather than generated by the new implementation.
func TestScoringReplayCompatibility(t *testing.T) {
	cases := []struct {
		name     string
		hand     card.Cards
		tile     card.Card
		discard  bool
		expected string
	}{
		{"straight_self_draw", card.Cards{"B1", "B2", "B3", "B4", "B5", "B6", "B7", "B8", "B9", "T1", "T1", "T1", "W9"}, "W9", false, "847e5dab6e7745f051b55d54af005da8274d4f6cbdd59dbb9207e797d973a8c3"},
		{"straight_discard_win", card.Cards{"B1", "B2", "B3", "B4", "B5", "B6", "B7", "B8", "B9", "T1", "T1", "T1", "W9"}, "W9", true, "c4334d0206a0038713ad67fe72d85c186b1be9386b1dab5f8269a53764825715"},
		{"seven_pairs", card.Cards{"B1", "B1", "B2", "B2", "B4", "B4", "T1", "T1", "T3", "T3", "W5", "W5", "W9"}, "W9", false, "c598e7eb3daa989ba34ff46ae953accd4d6edb8e4fa88e0f09094618c2941965"},
		{"orphans", card.Cards{"B1", "B9", "T1", "T9", "W1", "W9", "D", "N", "X", "B", "Z", "F", "W"}, "B1", false, "3032a97d13013d9544e4e82ec665300a66ed7e716e5ebb7be21b0a89bf296933"},
		{"standard_before_pairs", card.Cards{"B1", "B1", "B2", "B2", "B3", "B3", "T1", "T1", "T2", "T2", "T3", "T3", "W9"}, "W9", false, "05dc0c6bbab9c391c525573c2f1016f0189024d442672f4d981bf9cf62034c43"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			prefix, suffix := card.Cards{tc.tile}, card.Cards{}
			if tc.discard {
				prefix = card.Cards{"X"}
				suffix = card.Cards{tc.tile}
			}
			initial := scenario(t, tc.hand, prefix, suffix)
			f := recordGame(t, 1, &initial, nil)
			data, err := json.Marshal(f.Frames)
			if err != nil {
				t.Fatal(err)
			}
			got := fmt.Sprintf("%x", sha256.Sum256(data))
			if got != tc.expected {
				t.Fatalf("replay changed: got %s want %s", got, tc.expected)
			}
			if err := VerifyReplay(f); err != nil {
				t.Fatal(err)
			}
		})
	}
	for seed, expected := range map[int64]string{1: "19f71d7e45cbd8a4082590cdd67b8b23f4aaada790bd8f23c812370d0376c4f0", 2: "ea2d53a1265095693032f5cb3f88a85adeca7623a58194f7aa77926dea39c4d1", 42: "d643989768998e2e7bc1411bf7b3df9f6379a000292b1ec30b6d13d867f74559"} {
		f := recordGame(t, seed, nil, replay.SourceFunc(autoAction))
		data, _ := json.Marshal(f.Frames)
		if got := fmt.Sprintf("%x", sha256.Sum256(data)); got != expected {
			t.Fatalf("seed %d replay changed: got %s want %s", seed, got, expected)
		}
	}
}
